195	            toast({ title: "コピーしました", description: "登録用リンクをクリップボードにコピーしました。" });
196	        }).catch(err => {
197	            console.error('Failed to copy: ', err);
198	            toast({ variant: 'destructive', title: "コピー失敗", description: "リンクのコピーに失敗しました。" });
199	        });
200	    }, [url, toast]);
201	
202	    return (
203	        <div className="text-center flex flex-col items-center">
204	            <p className="text-4xl font-bold mb-4">QRコード登録</p>
205	            <div className="bg-white p-4 rounded-lg">
206	                <Image
207	                    src={`https://api.qrserver.com/v1/create-qr-code/?size=256x256&data=${encodeURIComponent(url)}`}
208	                    width={256}
209	                    height={256}
210	                    alt="QR Code"
211	                    data-ai-hint="qr code"
212	                    priority
213	                />
214	            </div>
215	            <p className="mt-4 text-xl max-w-md">スマートフォンでQRコードを読み取り登録を完了してください。</p>
216	            <div className="mt-4 flex items-center gap-2 bg-gray-800 px-4 py-2 rounded-lg max-w-2xl">
